		'gd_blacklist_action'  => kk_f( 'guard', 'select', __( 'What happens to a blocked number', 'kenakata-kit' ), __( '"Pay first" needs bKash / Nagad / Rocket (Mobile payment) to be on; without it the order is refused.', 'kenakata-kit' ), array( 'options' => array( 'block' => __( 'Refuse the order', 'kenakata-kit' ), 'advance' => __( 'Pay first: no cash on delivery', 'kenakata-kit' ) ), 'show_if' => 'gd_blacklist_enable' ) ),
		'gd_blacklist_msg'     => kk_f( 'guard', 'text', __( 'Message for a blocked number', 'kenakata-kit' ), '', array( 'show_if' => 'gd_blacklist_enable' ) ),
