		'gd_risk_enable'       => kk_f( 'guard', 'toggle', __( 'Ask customers with many returns to pay first', 'kenakata-kit' ), __( 'Cash on delivery is hidden for them; they pay with bKash / Nagad / Rocket (turn on Mobile payment, e.g. with "Only the delivery charge").', 'kenakata-kit' ) ),
		'gd_risk_min'          => kk_f( 'guard', 'number', __( 'Only after this many finished orders', 'kenakata-kit' ), __( 'New customers are never affected.', 'kenakata-kit' ), array( 'min' => 1, 'max' => 20, 'unit' => __( 'orders', 'kenakata-kit' ), 'show_if' => 'gd_risk_enable' ) ),
