		'bbar_label_size'      => kk_f( 'mobile', 'number', __( 'Label size', 'kenakata-kit' ), '', array( 'min' => 9, 'max' => 16, 'unit' => 'px' ) ),
		'h_bbar_colors'        => kk_f( 'mobile', 'heading', __( 'Colours', 'kenakata-kit' ) ),
