/** Options for the "Highlighted item" select. */
function kk_bbar_featured_options() {
	$out = array( '' => __( 'None', 'kenakata-kit' ) );
	foreach ( kk_bbar_default_items() as $it ) {
		$out[ $it['id'] ] = $it['label'];
	}
	return $out;
}
